// 由 scripts/gen-css.mjs 生成（`pnpm run gen:css`）：改样式请改那个 .css 文件后重新生成。
export const EXPLORER_CSS = "/* 工作区文件浏览器（dshpc-fb-*）。类名与 FileBrowser / preview 组件硬编码逐字一致。\n *\n * 度量口径：能用核心控件的一律核心（面包屑 = 核心 ghost 钮、行尾按钮 = 核心 outline 钮、\n * 展开开关 / 图标钮 = 核心 IconButton）；核心没有的那一项 = ▾ 选层浮层，按兄弟项目\n * dsh-task-dispatch-table 的 .dsh-tdt-sv-crumbs-*（archive-session-css.ts）逐条照抄：\n *   · 行 / 菜单圆角 6px（兄弟 --tdt-radius-sm 的实取值）⇒ 统一由 --fb-radius 一处定义；\n *   · 树行 padding 6px 8px / gap 8px；菜单条目 padding 4px 8px、最大宽 280px；\n *   · 下拉 max-height 240px 后滚动；空态与兄弟同款弱化。\n */\n.dshpc-fb{\n  --fb-radius:6px;\n  display:flex;flex-direction:column;height:100%;min-height:0;\n  color:var(--dshpc-fg);font-size:var(--dshpc-font-md);\n}\n\n/* 第一排：▾ 选层 + 面包屑 + 动作。\n   ⚠️ 不能 overflow:hidden —— 下拉浮层挂在它下面，裁了就看不见（兄弟项目四验真机 bug）。 */\n.dshpc-fb__bar{\n  position:relative;flex:none;display:flex;align-items:center;gap:2px;\n  padding:4px 10px;border-bottom:1px solid var(--dshpc-border-faint);white-space:nowrap;\n}\n.dshpc-fb__menu-wrap{position:relative;flex:none;display:inline-flex}\n.dshpc-fb__crumbs{position:relative;flex:1;min-width:0;display:flex;align-items:center;gap:2px;overflow:hidden}\n.dshpc-fb__crumbs-measure{position:absolute;top:0;left:0;display:inline-flex;align-items:center;gap:2px;visibility:hidden;pointer-events:none;white-space:nowrap}\n/* 面包屑 = 核心 ghost 钮（无底无边）：此处只补「可收缩 + 跑马灯占满」的布局，不改皮肤。 */\n.dshpc-fb__crumb{min-width:0;max-width:100%;font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-sm)}\n.dshpc-fb__crumb:disabled{color:var(--dshpc-fg-4);cursor:default}\n.dshpc-fb__crumb--current{color:var(--dshpc-fg);font-weight:600;cursor:default}\n.dshpc-fb__crumb-mq{flex:1 1 auto;min-width:0}\n.dshpc-fb__crumb-sep{color:var(--dshpc-fg-3);flex:none}\n.dshpc-fb__bar-plain{color:var(--dshpc-fg-2);font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-sm);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:default;user-select:none}\n.dshpc-fb__actions{display:flex;align-items:center;gap:4px;margin-left:auto;flex:none}\n\n/* ▾ 选层浮层（照抄兄弟 .dsh-tdt-sv-crumbs-*）：透明遮罩接「点外部」，菜单本体限高滚动。\n   层序必须高于 picker 面板（z-index 1100）——否则菜单开着时点面板不算「点外部」。 */\n.dshpc-fb__crumbs-backdrop{position:fixed;inset:0;z-index:1200;background:transparent}\n.dshpc-fb__crumbs-menu{\n  position:absolute;top:calc(100% + 4px);left:0;z-index:1201;min-width:160px;max-height:240px;overflow:auto;\n  background:var(--dshpc-surface-menu);border:1px solid var(--dshpc-border);box-shadow:0 4px 16px rgba(0,0,0,.18);\n  border-radius:var(--fb-radius);padding:4px;display:flex;flex-direction:column;\n}\n.dshpc-fb__menu-item{\n  appearance:none;background:0 0;border:none;text-align:left;font:inherit;\n  font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-md);color:var(--dshpc-fg);\n  padding:4px 8px;border-radius:var(--fb-radius);cursor:pointer;\n  max-width:280px;display:flex;align-items:center;gap:2px;\n  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.dshpc-fb__menu-item:hover{background:var(--dshpc-hover)}\n.dshpc-fb__menu-empty{font-size:var(--dshpc-font-sm);line-height:var(--dshpc-line-md);padding:4px 8px;color:var(--dshpc-fg-3)}\n.dshpc-fb__menu-icon{display:inline-flex;align-items:center;flex:none}\n.dshpc-fb__menu-chev{flex:none;color:var(--dshpc-fg-3);margin-right:1px}\n.dshpc-fb__menu-chev-slot{flex:none;width:11px;height:11px;margin-right:1px}\n.dshpc-fb__menu-label{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n/* 第二排（仅预览态）：文件名 + 工具（高度档统一 md，见组件注释）。 */\n.dshpc-fb__title{display:flex;align-items:center;gap:8px;padding:6px 8px;border-bottom:1px solid var(--dshpc-border-faint);min-width:0}\n.dshpc-fb__title-inner{font-size:var(--dshpc-font-md);font-weight:600}\n\n/* 主体 */\n.dshpc-fb__body{flex:1;min-height:0;display:flex;align-items:center;justify-content:center;padding:12px}\n.dshpc-fb__tree{flex:1;min-height:0;overflow:auto;padding:6px 8px}\n.dshpc-fb__note{padding:6px 10px;color:var(--dshpc-fg-3);font-size:var(--dshpc-font-sm)}\n.dshpc-fb__err{padding:6px 10px;color:var(--dshpc-fg-3);font-size:var(--dshpc-font-md);text-align:center}\n\n/* 树行（照抄兄弟 .dsh-tdt-sv-tree-row：gap 8 / padding 6px 8px / 圆角 6px） */\n.dshpc-fb__row{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:var(--fb-radius);cursor:pointer;user-select:none}\n.dshpc-fb__row:hover{background:var(--dshpc-hover)}\n.dshpc-fb__row:focus-visible{outline:2px solid var(--dshpc-focus);outline-offset:-2px}\n.dshpc-fb__row-icon{flex:none;display:inline-flex;color:var(--dshpc-fg-2)}\n.dshpc-fb__row-name{flex:1;min-width:0;font-size:var(--dshpc-font-md);line-height:var(--dshpc-line-md);color:var(--dshpc-fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n/* 行尾「进入 / 选择此文件夹」：核心 outline 钮，**平时隐身但占位**，悬停 / 聚焦该行才出现\n   （照抄兄弟 .dsh-tdt-sv-tree-act：opacity 0 + pointer-events none，出现时不顶动行内布局）。 */\n.dshpc-fb__row-act{flex:none;margin-left:auto;opacity:0;pointer-events:none;transition:opacity var(--dshpc-dur-fast,120ms) var(--dshpc-ease,ease)}\n.dshpc-fb__row:hover .dshpc-fb__row-act,.dshpc-fb__row-act:focus-visible{opacity:1;pointer-events:auto}\n.dshpc-fb__row-children{margin-left:9px;padding-left:7px;border-left:1px solid var(--dshpc-border-faint);display:flex;flex-direction:column}\n.dshpc-fb__row-note{padding:4px 8px;color:var(--dshpc-fg-3);font-size:var(--dshpc-font-sm)}\n.dshpc-fb__row-err{padding:4px 8px 4px 36px;color:var(--dshpc-danger);font-size:var(--dshpc-font-sm)}\n\n/* 预览体 */\n.dshpc-fb__text{flex:1;min-height:0;overflow:auto;width:100%}\n.dshpc-fb__banner{padding:6px 10px;background:var(--dshpc-open-bg-soft);color:var(--dshpc-fg-2);font-size:var(--dshpc-font-sm)}\n.dshpc-fb__more{display:flex;justify-content:center;padding:10px}\n.dshpc-fb__image{max-width:100%;border-radius:6px;border:1px solid var(--dshpc-border-faint)}\n.dshpc-fb__frame{flex:1;width:100%;height:100%;border:none;background:var(--dshpc-surface-1)}\n"
